#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <array>
#include <cassert>
#include <iostream>
// 가로4칸·세로4줄의 교육용 보드.
// 인덱스0이 바닥, 비트0이 오른쪽 끝이다.
int clearRows(std::array<int,4>& rows){
    for(int mask:rows)if(mask<0 || mask>15)return -1;
    std::array<int,4> next{{0,0,0,0}};
    int write=0, cleared=0;
    for(int mask:rows){
        if(mask==15)++cleared;
        else next[write++]=mask;
    }
    rows=next;return cleared;
}
int main(){
    std::array<int,4>a{{15,5,15,8}};
    assert(clearRows(a)==2);
    const std::array<int,4>expected{{5,8,0,0}};assert(a==expected);
    auto before=a;assert(clearRows(a)==0 && a==before);
    std::array<int,4>all{{15,15,15,15}};
    assert(clearRows(all)==4);
    const std::array<int,4>empty{{0,0,0,0}};assert(all==empty);
    std::array<int,4>bad{{15,16,0,0}};before=bad;
    assert(clearRows(bad)==-1 && bad==before);
    std::cout<<"row clear tests passed\n";
}
